+  ANALYTICS_EVENT = 'Wallet Connect QR Scan';
+  constructor({
+    actions,
+    onError,
+    qrcode = true,
+    qrcodeModalOptions,
+  }: Omit<WalletConnectConstructorArgs, 'options'> & {
+    qrcode?: boolean;
+    qrcodeModalOptions?: IQRCodeModalOptions;
